-- NextGen Miner: additional owner-controlled manual deposit destinations.
-- User-supplied addresses. QR assets are bundled under assets/deposit/qr/.
-- Coin-specific min deposit / confirmations / network fee remain NULL until explicitly configured by owner.

on conflict (asset,network) do update set provider=excluded.provider,destination=excluded.destination,label=excluded.label,min_deposit=excluded.min_deposit,confirmations_required=excluded.confirmations_required,network_fee=excluded.network_fee,warning_title=excluded.warning_title,warning_message=excluded.warning_message,first_deposit_note=excluded.first_deposit_note,qr_code_path=excluded.qr_code_path,active=excluded.active,is_active=excluded.is_active;
